version.transform:
(
  $data := $ 
    ~> | $ | {
      "category": $moment(startAt).format("MM/DD/YYYY HH")
    } |;

  $groupedData := ($data{
    category: {
      "category": $first(category),
      "production": $sum(totalProductionQuantity[$not($isNil($))]),
      "scrap": $sum(totalScrapQuantity[$not($isNil($))])
    }
  } ~> $values)^(category);

  $avgP := $round($average($groupedData.production), 2);
  $avgS := $round($average($groupedData.scrap), 2);

  {
    "categories": [
        {
            "category": [$groupedData.{
              "label": category
            }]
        }
    ],
    "dataSet": [
        {
          "seriesname":"Production",
          "data": [$groupedData.{
          "value": production
        }]
        },
        {
        "seriesname":"Scrap",
          "data": [$groupedData.{
          "value": scrap
        }]
        }
    ],
    "trendlines": [
      {
        "line": [

          {
            "startvalue": $avg,
            "color": "#43a047",
            "displayvalue": "Avg Production: " & $string($avgP),
            "valueOnRight": true
          },
           {
            "startvalue": $avg,
            "color": "#c02723",
            "displayvalue": "Avg Scrap: " & $string($avgS),
            "valueOnRight": true
          }
        ]
      }
    ]
  }
)
